import{_ as i,o as e,c as l,ae as t}from"./chunks/framework.FQ5RHm_v.js";const c=JSON.parse('{"title":"wvke-sdk | パーフェクトカスタマイゼーション！","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | パーフェクトカスタマイゼーション！","titleTemplate":false},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md"}'),s={name:"ja/index.md"};function d(r,a,n,o,h,p){return e(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk は、キーボードやマウスなどのゲーミングペリフェラルと通信するための JavaScript SDK です。</p><p>最新の WebHID テクノロジースタックをベースに、キーボード、マウス、その他ペリフェラルの高度なカスタマイズとインテリジェント制御を実現します。ゲーミングペリフェラル製品のエンドツーエンドの提供を加速し、ゲーミングエコシステム全体に新たな可能性を開くことを目的としています。本プロジェクトは GDE Game Driver Engine Team によって開発・保守されています。</p><h2 id="sdk-タイプ" tabindex="-1">SDK タイプ <a class="header-anchor" href="#sdk-タイプ" aria-label="Permalink to &quot;SDK タイプ&quot;">​</a></h2><h3 id="⌨️-リニアキーボード" tabindex="-1">⌨️ リニアキーボード <a class="header-anchor" href="#⌨️-リニアキーボード" aria-label="Permalink to &quot;⌨️ リニアキーボード&quot;">​</a></h3><p>メカニカルキーボード向けに構築：</p><ul><li>キーマッピングとレイヤー切り替え</li><li>RGB ライティング制御</li><li>WebHID 認証、認証済みデバイス一覧、デバイス初期化</li><li>RT 全行程スイッチ、作動トラベル、セーフゾーン調整</li><li>マクロ記録と再生</li><li>ポーリングレート調整（1KHz-8KHz）</li><li>システムモード切替（Windows/Mac）</li></ul><h3 id="🖱️-マウス-sdk" tabindex="-1">🖱️ マウス SDK <a class="header-anchor" href="#🖱️-マウス-sdk" aria-label="Permalink to &quot;🖱️ マウス SDK&quot;">​</a></h3><p>ゲーミングマウス向けに構築：</p><ul><li>DPI 調整（400-16000 DPI）</li><li>ボタンプログラミングとマクロ</li><li>RGB ライティングカスタマイズ</li><li>リフトオフ距離調整</li><li>ポーリング最適化</li></ul><h2 id="特徴" tabindex="-1">特徴 <a class="header-anchor" href="#特徴" aria-label="Permalink to &quot;特徴&quot;">​</a></h2><ul><li>モダンな JavaScript/TypeScript サポート</li><li>WebHID ハードウェア通信</li><li>完全なライティング制御 API</li><li>キーマッピングとマクロ API</li><li>RT トラベル、高度なキー API、デバイス初期化</li><li>マウス DPI とボタンマッピング API</li><li>汎用カスタムアップグレードサービス</li><li>詳細な API ドキュメント</li></ul><h2 id="チュートリアル" tabindex="-1">チュートリアル <a class="header-anchor" href="#チュートリアル" aria-label="Permalink to &quot;チュートリアル&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>詳細な使い方は <a href="/wvke.sdkdoc/docs/ja/api/info.html">API ドキュメント</a> をご参照ください。</p>',15)])])}const u=i(s,[["render",d]]);export{c as __pageData,u as default};
